SELECT organization_id AS organizationId,organization_code AS organizationCode,parent_organization_code AS parentOrganizationCode,organization_name AS organizationName,organization_type AS organizationType,sort_order AS sortOrder,effective_from AS effectiveFrom,effective_to AS effectiveTo,use_yn AS useYn,version_no AS versionNo,updated_at AS updatedAt FROM MBW_ORGANIZATION ORDER BY sort_order,organization_code OFFSET :offset ROWS FETCH NEXT :limit ROWS ONLY
